use glam::{DMat4,DVec3};
use ingetrazo_core::{scene::{Scene,SelectionItem},mesh::Mesh,groups::Group,image_plane::ImagePlane,math::Ray};
use ingetrazo_gui::app::IngeTrazoApp;
use ingetrazo_tools::base::{ToolContext,ToolType};
use serde_json::{Value,json};
fn vec(v:&Value)->DVec3{DVec3::new(v[0].as_f64().unwrap(),v[1].as_f64().unwrap(),v[2].as_f64().unwrap())}
fn mesh(m:&Mesh)->Value{json!({"vertices":m.vertices.iter().map(|v|v.position.to_array()).collect::<Vec<_>>(),"faces":m.faces.iter().map(|f|json!({"vertices":f.vertices.iter().map(|&i|m.vertices[i].position.to_array()).collect::<Vec<_>>(),"attrs":f.attrs})).collect::<Vec<_>>()})}
fn state(a:&IngeTrazoApp)->Value{json!({"mesh":mesh(&a.scene.mesh),"groups":a.scene.groups.iter().map(|g|json!({"mesh":mesh(&g.mesh),"transform":if g.native_document.get("xform").is_some_and(|v|!v.is_null()){Some(g.transform.to_cols_array())}else{None},"axes":g.axes_matrix().map(|m|m.to_cols_array())})).collect::<Vec<_>>(),"images":a.scene.image_planes.iter().map(|i|[i.origin.to_array(),i.u.to_array(),i.v.to_array()]).collect::<Vec<_>>(),"undo":a.undo_stack.len(),"redo":a.redo_stack.len()})}
fn context(p:DVec3,ctrl:bool)->ToolContext{ToolContext::with_modifiers(p,Ray::new(p+DVec3::Z*10.,-DVec3::Z),false,ctrl,false)}
fn main(){let args=std::env::args().collect::<Vec<_>>();let source:Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let mut rows=vec![];
for row in source["cases"].as_array().unwrap(){let kind=row["kind"].as_str().unwrap();let mut app=IngeTrazoApp::new();app.scene=Scene::new();let mut m=Mesh::new();let vertices=[DVec3::ZERO,DVec3::new(2.,0.,0.),DVec3::new(2.,3.,0.),DVec3::new(0.,3.,0.)].map(|p|m.add_vertex(p));m.add_face(vertices.to_vec(),vec![]);m.faces[0].attrs=serde_json::from_value(json!({"vendor":71,"texture":{"path":"scan","uvw":[0.25,0,0,0.1,0,0.5,0,0.2]}})).unwrap();
if matches!(kind,"loose"|"mixed"){app.scene.mesh=m;app.scene.select(SelectionItem::Face(0));}
else if kind!="image"{let mut g=Group::with_mesh(kind,m.clone());let transform=DMat4::from_cols_array(&[0.8,0.6,0.,0.,-0.6,0.8,0.,0.,0.,0.,if kind=="reflected"{-1.}else{1.},0.,3.,-2.,1.,1.]).as_mat4().as_dmat4();if matches!(kind,"placed"|"reflected"){g.transform=transform;g.native_document=json!({"xform":transform.to_cols_array()});}if kind=="baked-rotated"{g.native_document=json!({"axes":transform.to_cols_array()});}app.scene.groups.push(g);
if kind.starts_with("shared"){let token=uuid::Uuid::new_v4();app.scene.register_mesh_share(token,m.clone()).unwrap();app.scene.groups[0].mesh_share=Some(token);let mut sibling=Group::with_mesh("sibling",m.clone());sibling.mesh_share=Some(token);app.scene.groups.push(sibling);app.scene.groups.push(Group::with_mesh("independent equal",m));}
app.scene.select(SelectionItem::Group(0));if kind=="shared-two"{app.scene.select(SelectionItem::Group(1));}}
if matches!(kind,"image"|"mixed"){app.scene.image_planes.push(ImagePlane::new("scan",DVec3::new(1.,2.,0.),DVec3::new(2.,0.,0.),DVec3::new(0.,3.,0.)));app.scene.select(SelectionItem::ImagePlane(0));}
app.set_tool(ToolType::Scale);let mut states=serde_json::Map::new();states.insert("before".into(),state(&app));app.dispatch_tool_click(&context(vec(&row["grab"]),false));states.insert("grab".into(),state(&app));app.dispatch_tool_move(&context(vec(&row["hover"]),false));states.insert("preview".into(),state(&app));app.dispatch_tool_control_state(true);states.insert("center".into(),state(&app));let accepted=app.dispatch_tool_vcb("2").is_ok();states.insert("commit".into(),state(&app));let retype=app.dispatch_tool_vcb("-1").is_ok();states.insert("retype".into(),state(&app));app.undo();states.insert("undo".into(),state(&app));app.redo();states.insert("redo".into(),state(&app));app.dispatch_tool_click(&context(vec(&row["cancel_grab"]),true));app.dispatch_tool_move(&context(vec(&row["cancel_hover"]),true));states.insert("cancel-preview".into(),state(&app));app.dispatch_tool_cancel();states.insert("cancel".into(),state(&app));let registry_consistent=app.scene.groups.iter().all(|g|g.mesh_share.is_none_or(|token|app.scene.mesh_shares.get(&token)==Some(&g.mesh)));
rows.push(json!({"kind":kind,"accepted":[accepted,retype],"states":states,"registry_consistent":registry_consistent}));}
let mut warp=IngeTrazoApp::new();warp.scene=Scene::new();let ids=[DVec3::ZERO,DVec3::X,DVec3::new(1.,1.,0.),DVec3::Y].map(|p|warp.scene.mesh.add_vertex(p));warp.scene.mesh.add_face(ids.to_vec(),vec![]);warp.scene.mesh.faces[0].attrs.insert("vendor".into(),json!(71));let other=warp.scene.mesh.add_vertex(DVec3::new(2.,0.,1.));let e=warp.scene.mesh.add_edge(0,other).unwrap();warp.scene.select(SelectionItem::Edge(e));warp.set_tool(ToolType::Scale);let mut states=serde_json::Map::new();states.insert("before".into(),state(&warp));warp.dispatch_tool_click(&context(DVec3::ZERO,false));let a=warp.dispatch_tool_vcb("2").is_ok();states.insert("commit".into(),state(&warp));let b=warp.dispatch_tool_vcb("3").is_ok();states.insert("retype".into(),state(&warp));warp.undo();states.insert("undo".into(),state(&warp));warp.redo();states.insert("redo".into(),state(&warp));
std::fs::write(&args[2],serde_json::to_vec_pretty(&json!({"cases":rows,"warp":{"accepted":[a,b],"states":states}})).unwrap()).unwrap();}
